initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT contains a Context Source Registration 
        with id equal to ${context_source_registration_id}
        and payload set to ${context_source_registration_payload_file_path}
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Query Context Source Registrations with Response Status Code set to 200     and
        Notification with Response body set to list of all matching Context Source Registrations resolved against the default JSON-LD context
}

